100	  process.exit(1); // Crash fast — Railway/PM2 will restart. Zombie processes cause worse problems.
101	});
102	process.on('unhandledRejection', (reason) => {
103	  console.error('[UNHANDLED REJECTION]', reason);
104	  process.exit(1);
105	});
