107	// ── Graceful shutdown (SIGTERM from Railway/Docker/PM2) ───────────────────────
108	let isShuttingDown = false;
109	function gracefulShutdown(signal) {
110	  if (isShuttingDown) return;
111	  isShuttingDown = true;
112	  console.log(`[server] ${signal} received — shutting down gracefully`);
113	  // Give in-flight SSE streams 5s to finish, then force-quit
114	  const timeout = setTimeout(() => {
115	    console.log('[server] Graceful shutdown timeout — forcing exit');
116	    process.exit(0);
117	  }, 5000);
118	  if (timeout.unref) timeout.unref();
119	  try {
120	    const db = require('./db');
121	    if (typeof db.close === 'function') db.close();
122	  } catch { /* db may not be init'd */ }
123	  process.exit(0);
124	}
125	process.on('SIGTERM', () => gracefulShutdown('SIGTERM'));
126	process.on('SIGINT', () => gracefulShutdown('SIGINT'));
