128	// ── Start ─────────────────────────────────────────────────────────────────────
129	const PORT = process.env.PORT || 3847;
130	const HOME = os.homedir();
131	const CLAUDE_DIR = path.join(HOME, '.claude');
132	const CONFIG_PATH = path.join(__dirname, '..', 'config.json');
