134	app.listen(PORT, () => {
135	  console.log('');
136	  console.log('  ╔══════════════════════════════════════╗');
137	  console.log('  ║          Polyglot is running          ║');
138	  console.log(`  ║     http://localhost:${PORT}            ║`);
139	  console.log('  ╚══════════════════════════════════════╝');
140	  console.log('');
141	  console.log(`  Claude dir: ${CLAUDE_DIR}`);
142	  console.log(`  Config: ${CONFIG_PATH}`);
143	
144	  // Restore scheduled cron jobs
145	  bootSchedules();
146	
147	  // Start backup service (watcher + safety net) if configured
148	  try {
149	    backup.startBackupService();
150	  } catch (err) {
151	    console.log(`  Backup: failed to start — ${err.message}`);
152	  }
153	
154	  // Agent sync: reconcile disk ↔ SQLite registry, then watch for live changes.
155	  try {
156	    const summary = agentSync.reseedFromDisk();
157	    console.log(`  AgentSync: reseeded ${summary.upserted}/${summary.scanned} (${summary.removed} retired, ${summary.errors.length} errors)`);
158	    agentSync.startWatcher();
159	  } catch (err) {
160	    console.log(`  AgentSync: failed to start — ${err.message}`);
161	  }
162	
163	  // Org JSON file-watcher: re-seed registry + departments into SQLite when the
164	  // source-of-truth files at ~/.claude/org/ change on disk. Lets users edit
165	  // registry.json or departments.json directly and see the org chart update
166	  // within a few seconds — no server restart required.
167	  try {
168	    const chokidar = require('chokidar');
169	    const orgLib = require('./org');
170	    const ORG_DIR = path.dirname(orgLib.REGISTRY_PATH);
171	    const DEPTS_PATH = path.join(ORG_DIR, 'departments.json');
172	
173	    // Boot-time load: ensure SQLite departments + agent fields reflect
174	    // whatever's currently on disk. Without this, edits made while the
175	    // server was stopped won't propagate (the migration v4/v5 importers
176	    // only run on schema bumps, not regular startups).
177	    try {
178	      if (fs.existsSync(DEPTS_PATH)) {
179	        const parsed = JSON.parse(fs.readFileSync(DEPTS_PATH, 'utf-8'));
180	        db.saveDepartments(parsed);
181	        console.log(`  OrgWatch: bootstrapped departments.json into SQLite (version ${parsed.version || '?'})`);
182	      }
183	      if (fs.existsSync(orgLib.REGISTRY_PATH)) {
184	        const reg = JSON.parse(fs.readFileSync(orgLib.REGISTRY_PATH, 'utf-8'));
185	        if (reg.agents) {
186	          // Patch agent dept/subDept/pod/secondaryReportsTo + tags/squad
187	          // for every agent already known to SQLite. This mirrors the v4/v5
188	          // migration logic but runs every boot for resilience.
189	          const sqlitedb = db.getDb();
190	          const updateStmt = sqlitedb.prepare(
191	            'UPDATE agents SET department=?, subDepartment=?, pod=?, secondaryReportsTo=? WHERE id=?'
192	          );
193	          let touched = 0;
194	          for (const [id, a] of Object.entries(reg.agents)) {
195	            try {
196	              updateStmt.run(
197	                a.department || null,
198	                a.subDepartment || null,
199	                a.pod || null,
200	                a.secondaryReportsTo || null,
201	                id,
202	              );
203	              touched += 1;
204	            } catch { /* row may not exist yet — agentSync.reseedFromDisk will INSERT */ }
205	          }
206	          console.log(`  OrgWatch: bootstrapped registry.json fields into SQLite (${touched} agents touched, version ${reg.version || '?'})`);
207	        }
208	      }
209	    } catch (err) {
210	      console.warn(`  OrgWatch: bootstrap load failed: ${err.message}`);
211	    }
212	
213	    const orgWatcher = chokidar.watch([
214	      orgLib.REGISTRY_PATH,
215	      DEPTS_PATH,
216	    ], { ignoreInitial: true, awaitWriteFinish: { stabilityThreshold: 400, pollInterval: 100 } });
217	    let reseedTimer = null;
218	    const queueReseed = (filePath) => {
219	      // Debounce — multiple writes in the same atomic-rename burst trigger
220	      // a single reseed.
221	      if (reseedTimer) clearTimeout(reseedTimer);
222	      reseedTimer = setTimeout(() => {
223	        const baseName = path.basename(filePath);
224	        try {
225	          // Bug 9 fix: when departments.json changes, push the new content
226	          // into SQLite (db.loadDepartments reads from SQLite, not the JSON
227	          // file). Without this, edits to ~/.claude/org/departments.json are
228	          // silently ignored by the running server.
229	          if (baseName === 'departments.json') {
230	            const fileContent = fs.readFileSync(DEPTS_PATH, 'utf-8');
231	            const parsed = JSON.parse(fileContent);
232	            db.saveDepartments(parsed);
233	            console.log(`[org-watch] departments.json reloaded into SQLite (${Object.keys(parsed.departments || {}).length} depts, version ${parsed.version})`);
234	          }
235	          // Reseed agent .md files into SQLite (registry.json edits propagate
236	          // through this path too, since the registry is rebuilt from .md
237	          // frontmatter on every reseed).
238	          const sum = agentSync.reseedFromDisk();
239	          console.log(`[org-watch] ${baseName} changed → reseeded ${sum.upserted}/${sum.scanned}`);
240	          agentSync.events.emit('taxonomy:update', { ts: Date.now(), reason: 'org-files-changed', file: baseName });
241	        } catch (err) {
242	          console.warn(`[org-watch] reseed failed: ${err.message}`);
243	        }
244	      }, 500);
245	    };
246	    orgWatcher.on('change', queueReseed);
247	    orgWatcher.on('add', queueReseed);
248	    console.log('  OrgWatch: chokidar watching registry.json + departments.json');
249	  } catch (err) {
250	    console.log(`  OrgWatch: failed to start — ${err.message}`);
251	  }
252	
253	  // Auto-backup SQLite data on startup + every 6 hours
254	  try { db.autoBackupToFile(); } catch {}
255	  setInterval(() => { try { db.autoBackupToFile(); } catch {} }, 6 * 60 * 60 * 1000);
256	
257	  // ── HR cron jobs ──────────────────────────────────────────────────────────
258	  // Roster nightly recompute (02:00 UTC) — refreshes experience profiles
259	  // Witness daily sweep (03:00 UTC) — classifies yesterday's runs
260	  // Cadence weekly review (Monday 09:00 UTC) — applies promotions + PIPs
261	  try {
262	    cron.schedule('0 2 * * *', () => {
263	      try {
264	        const summary = experience.recomputeAllExperience(org);
265	        console.log(`[HR] Roster nightly recompute: ${summary.updated}/${summary.total}`);
266	      } catch (err) {
267	        console.warn(`[HR] Roster recompute failed: ${err.message}`);
268	      }
269	    }, { timezone: 'Etc/UTC' });
270	
271	    cron.schedule('0 3 * * *', () => {
272	      try {
273	        const recent = loadRecentAgentRuns(24);
274	        const result = hr.runWitnessSweep(org, experience, recent);
275	        console.log(`[HR] Witness sweep: ${result.runsClassified} runs, ${result.pipCandidates.length} PIP, ${result.promotionCandidates.length} promo`);
276	      } catch (err) {
277	        console.warn(`[HR] Witness sweep failed: ${err.message}`);
278	      }
279	
280	      // Sprint 5 — auto-advance any open escalation past its tier SLA
281	      // (24h specialist → pod-lead → vp → yash). Runs alongside Witness so
282	      // SLA breaches surface in the same daily ops digest.
283	      try {
284	        const escalation = require('./lib/escalation');
285	        const advanced = escalation.autoAdvanceExpired();
286	        if (advanced.length > 0) {
287	          console.log(`[HR] Escalation SLA sweep: advanced ${advanced.length} stale escalation(s)`);
288	        }
289	      } catch (err) {
290	        console.warn(`[HR] Escalation SLA sweep failed: ${err.message}`);
291	      }
292	
293	      // Phase B — reconcile per-agent active_task_count against the tasks
294	      // table in case any state got dropped (crashed mid-transaction etc.).
295	      // Cheap UPDATE — runs in a single statement.
296	      try {
297	        const tasks = require('./lib/tasks');
298	        tasks.reconcileLoad();
299	      } catch (err) {
300	        console.warn(`[HR] Task load reconcile failed: ${err.message}`);
301	      }
302	    }, { timezone: 'Etc/UTC' });
303	
304	    cron.schedule('0 9 * * 1', () => {
305	      try {
306	        const recent = loadRecentAgentRuns(24 * 7);
307	        const review = hr.runCadenceReview(org, experience, recent);
308	        console.log(`[HR] Cadence weekly review ${review.week}: ${review.promotions.length} promotions, ${review.pipsOpened.length} PIPs`);
309	      } catch (err) {
310	        console.warn(`[HR] Cadence review failed: ${err.message}`);
311	      }
312	    }, { timezone: 'Etc/UTC' });
313	
314	    console.log('  HR: cron jobs scheduled (Roster 02:00, Witness 03:00, Cadence Mon 09:00 UTC)');
315	  } catch (err) {
316	    console.warn(`  HR: cron scheduling failed — ${err.message}`);
317	  }
318	
319	  console.log('');
320	});
