26	function snapshotAgent(agentName, content) {
27	  const agentDir = path.join(VERSIONS_DIR, agentName);
28	  if (!fs.existsSync(agentDir)) fs.mkdirSync(agentDir, { recursive: true });
29	  const ts = new Date().toISOString().replace(/[:.]/g, '-');
30	  atomicWriteText(path.join(agentDir, `${ts}.md`), content);
31	  const versions = fs.readdirSync(agentDir).filter(f => f.endsWith('.md')).sort().reverse();
32	  for (const old of versions.slice(20)) {
33	    try { fs.unlinkSync(path.join(agentDir, old)); } catch {}
34	  }
35	}
