38	router.get('/global/agents', (req, res) => {
39	  const dir = path.join(CLAUDE_DIR, 'agents');
40	  if (req.query.full === '1') {
41	    return res.json(listAgents(dir));
42	  }
43	  res.json(listAgentsMeta(dir));
44	});
