46	// GET /api/global/agents/:name
47	router.get('/global/agents/:name', validateName, (req, res) => {
48	  const filePath = path.join(CLAUDE_DIR, 'agents', req.params.name + '.md');
49	  if (req.query.meta === '1') {
50	    const meta = parseAgentMeta(filePath);
51	    if (!meta) return res.status(404).json({ error: 'Not found' });
52	    return res.json(meta);
53	  }
54	  const agent = parseAgent(filePath);
55	  if (!agent) return res.status(404).json({ error: 'Not found' });
56	  res.json(agent);
57	});
