59	// PUT /api/global/agents/:name
60	router.put('/global/agents/:name', validateName, (req, res) => {
61	  if (typeof req.body.content !== 'string') return res.status(400).json({ error: 'content must be a string' });
62	  const dir = path.join(CLAUDE_DIR, 'agents');
63	  ensureDir(dir);
64	  const filePath = path.join(dir, req.params.name + '.md');
65	
66	  if (process.env.POLYGLOT_BUDGET_ENFORCE !== '0' && req.query.force !== '1') {
67	    try {
68	      const { checkBudget } = require('../compactor/budget');
69	      const check = checkBudget({ agentId: req.params.name, content: req.body.content });
70	      if (!check.ok) {
71	        return res.status(409).json({
72	          error: 'over_budget',
73	          message: `Agent body exceeds budget. Run the compactor or append ?force=1 to override.`,
74	          budget: check.budget,
75	          actual: check.actual,
76	          violations: check.violations,
77	          runCompactor: check.suggestion,
78	        });
79	      }
80	      if (check.warnings.length > 0) res.setHeader('X-Budget-Warnings', JSON.stringify(check.warnings));
81	    } catch (err) {
82	      console.warn(`[budget] check failed for ${req.params.name}: ${err.message}`);
83	    }
84	  }
85	
86	  if (fs.existsSync(filePath)) {
87	    try { snapshotAgent(req.params.name, fs.readFileSync(filePath, 'utf-8')); } catch {}
88	  }
89	  atomicWriteText(filePath, req.body.content);
90	  res.json({ ok: true, agent: parseAgent(filePath) });
91	});
