160	router.post('/agents/:name/health', validateName, (req, res) => {
161	  const { scope, projectId, content } = req.body || {};
162	  let filePath = null;
163	  let raw = typeof content === 'string' ? content : null;
164	
165	  if (!raw) {
166	    if (scope === 'project' && projectId) {
167	      const projects = discoverProjects(loadConfig().projectDirs);
168	      const proj = projects.find(p => p.id === projectId);
