18	
19	function getDb() {
20	  if (_db) return _db;
21	  fs.mkdirSync(DB_DIR, { recursive: true });
22	  _db = new Database(DB_PATH);
23	  _db.pragma('journal_mode = WAL');
24	  _db.pragma('foreign_keys = ON');
25	  _db.pragma('busy_timeout = 5000');
26	  _db.pragma('synchronous = NORMAL');
27	  _db.pragma('auto_vacuum = INCREMENTAL'); // Q12: reclaim space incrementally
28	  _db.pragma('cache_size = -64000');       // 64MB page cache (default is 2MB)
29	  _db.pragma('temp_store = MEMORY');       // temp tables in RAM, not disk
30	
31	  // Integrity check — catch corruption early
32	  try {
33	    const check = _db.pragma('integrity_check');
34	    if (check[0]?.integrity_check !== 'ok') {
35	      console.error('[db] INTEGRITY CHECK FAILED:', check);
36	    }
37	  } catch (err) {
38	    console.error('[db] Integrity check error:', err.message);
39	  }
40	
41	  runMigrations(_db);
42	  return _db;
43	}
44	
45	function close() {
46	  if (_db) { _db.close(); _db = null; }
47	}
