59	function runMigrations(db) {
60	  db.exec(`CREATE TABLE IF NOT EXISTS schema_migrations (
61	    version INTEGER PRIMARY KEY,
62	    name TEXT NOT NULL,
63	    applied_at TEXT NOT NULL DEFAULT (datetime('now'))
64	  )`);
65	
66	  const applied = new Set(db.prepare('SELECT version FROM schema_migrations').all().map(r => r.version));
67	
68	  const migrations = [
69	    { version: 1, name: 'create_all_tables', fn: createAllTables },
70	    { version: 2, name: 'import_json_data', fn: importJsonData },
71	    { version: 3, name: 'create_change_log', fn: createChangeLog },
72	    { version: 4, name: 'org_structure_v2', fn: orgStructureV2Migration },
73	    { version: 5, name: 'tags_squad_history', fn: tagsSquadHistoryMigration },
74	    { version: 6, name: 'tasks_table', fn: tasksTableMigration },
75	    { version: 7, name: 'agent_capacity_columns', fn: agentCapacityMigration },
76	    { version: 8, name: 'orchestration_runtime', fn: orchestrationRuntimeMigration },
77	    { version: 9, name: 'node_positions', fn: nodePositionsMigration },
78	    { version: 10, name: 'node_positions_locked', fn: nodePositionsLockedMigration },
79	    { version: 11, name: 'agent_avatar', fn: agentAvatarMigration },
80	    { version: 12, name: 'agent_gender', fn: agentGenderMigration },
81	  ];
82	
83	  for (const mig of migrations) {
84	    if (applied.has(mig.version)) continue;
85	    console.log(`[db] Running migration ${mig.version}: ${mig.name}`);
86	    db.transaction(() => {
87	      mig.fn(db);
88	      db.prepare('INSERT INTO schema_migrations (version, name) VALUES (?, ?)').run(mig.version, mig.name);
89	    })();
90	  }
