200	// Cascade delete — strips the tag from every agent's tag-array in this
201	// category, then deletes the tag from the taxonomy.
202	function cascadeDeleteTag(category, tag, orgModule) {
203	  const data = readJson(TAGS_PATH, { version: 1, categories: {} });
204	  if (!data.categories?.[category]?.tags?.[tag]) {
205	    throw new Error(`Tag "${tag}" not found in "${category}"`);
206	  }
207	  const agents = orgModule.listAgentRecords();
208	  const affected = agents.filter(a => (a.tags?.[category] || []).includes(tag));
209	  for (const a of affected) {
210	    try {
211	      const nextTags = { ...(a.tags || {}) };
212	      nextTags[category] = (nextTags[category] || []).filter(t => t !== tag);
213	      orgModule.upsertAgent(a.id, { tags: nextTags });
214	    } catch (err) {
215	      console.warn(`[taxonomy] cascade clear tag failed for ${a.id}: ${err.message}`);
216	    }
217	  }
218	  return { ...deleteTag(category, tag, []), cascaded: affected.length };
219	}
