51	    ...config.projectDirs.map(d => path.resolve(d.replace(/^~/, HOME))),
52	  ];
53	  const isAllowed = allowedRoots.some(root =>
54	    projectPath === root || projectPath.startsWith(root + path.sep)
55	  );
