57	    return res.status(403).json({ error: 'Project outside allowed directories' });
58	  }
59	  if (!fs.existsSync(projectPath) || !fs.statSync(projectPath).isDirectory()) {
60	    return res.status(404).json({ error: 'Project directory not found' });
61	  }
62	  req.projectPath = projectPath;
