14	// Cost tier penalty for the dispatch scoring formula. Loaded from
15	// model_routing.json so it stays in sync with the policy file.
16	function tierCostPenalty(model) {
17	  if (!model) return 0.5;
18	  const m = String(model).toLowerCase();
19	  if (m.includes('opus')) return 1.0;
20	  if (m.includes('haiku')) return 0.05;
21	  if (m.includes('sonnet')) return 0.3;
22	  return 0.5;
23	}
24	
25	function priorityBoost(priority) {
26	  switch (priority) {
27	    case 'p0': return 0.3;
28	    case 'p1': return 0.15;
29	    case 'p2': return 0;
30	    case 'p3': return -0.05;
31	    default: return 0;
32	  }
33	}
