35	// Score formula:
36	//   skillScore * 0.5      ← skill match (0-1)
37	// + (1 - loadPct) * 0.2   ← favor less-loaded agents
38	// + successRate * 0.2     ← favor proven performers
39	// - costPenalty * costWeight ← break ties toward cheap agents (default 0.1)
40	// + priorityBoost         ← P0 lifts up, P3 nudges down
41	//
42	// `costWeight` is dynamic: when monthly burn > threshold and the task isn't
43	// in the exempt list, we crank cost penalty up to 0.45 so cheap (haiku) tier
44	// dominates. This implements model_routing.json's `downgrade_fast_to_cheap_
45	// for_non_critical` rule.
46	function rankCandidate(c, opts = {}) {
47	  const skill = c.skillScore || 0;
48	  const loadPct = c.maxConcurrentTasks > 0
49	    ? Math.min(1, (c.activeTaskCount || 0) / c.maxConcurrentTasks)
50	    : 1;
51	  const sr = typeof c.successRate === 'number' ? c.successRate : 0.7;
52	  const cost = tierCostPenalty(c.model);
53	  const costWeight = typeof opts.costWeight === 'number' ? opts.costWeight : 0.1;
54	
55	  const score =
56	      skill * 0.5
57	    + (1 - loadPct) * 0.2
58	    + sr * 0.2
59	    - cost * costWeight
60	    + priorityBoost(opts.priority);
61	
62	  return Math.max(0, score);
63	}
