65	// Compute budget context for a dispatch. Returns:
66	//   { overBudget: boolean, burnPct: number|null, costWeight: number,
67	//     downgrade: boolean, exemptTask: boolean }
68	//
69	// downgrade=true means we're past the 110% threshold AND the task isn't in
70	// the exempt list. costWeight gets cranked up to bias toward cheap tier.
71	function computeBudgetContext(taskType) {
72	  try {
73	    const policy = db.loadModelRouting() || {};
74	    const rules = policy.downgradeRules || [];
75	    const downgradeRule = rules.find((r) => r.trigger === 'monthly_burn_above_pct');
76	    if (!downgradeRule) return { overBudget: false, burnPct: null, costWeight: 0.1, downgrade: false, exemptTask: false };
77	
78	    // Compute current burn pct from last 30d agent_runs
79	    const cutoffMs = Date.now() - 30 * 24 * 3600 * 1000;
80	    const cutoffIso = new Date(cutoffMs).toISOString();
81	    const runs = db.getRecentAgentRuns(30 * 24);
82	    const totalCost = runs.reduce((acc, r) => {
83	      if (r.timestamp < cutoffIso) return acc;
84	      return acc + (r.estimatedCost || 0);
85	    }, 0);
86	    const totalBudget = policy.totalMonthlyBudgetUsd || 0;
87	    if (totalBudget <= 0) return { overBudget: false, burnPct: null, costWeight: 0.1, downgrade: false, exemptTask: false };
88	
89	    const burnPct = (totalCost / totalBudget) * 100;
90	    const overBudget = burnPct > (downgradeRule.threshold || 110);
91	    const exemptTasks = downgradeRule.exempt_tasks || [];
92	    const exemptTask = !!taskType && exemptTasks.includes(taskType);
93	    const downgrade = overBudget && !exemptTask;
94	
95	    return {
96	      overBudget,
97	      burnPct: Math.round(burnPct * 10) / 10,
98	      costWeight: downgrade ? 0.45 : 0.1,
99	      downgrade,
100	      exemptTask,
101	    };
102	  } catch (err) {
103	    console.warn('[dispatch] computeBudgetContext failed:', err.message);
104	    return { overBudget: false, burnPct: null, costWeight: 0.1, downgrade: false, exemptTask: false };
105	  }
106	}
